			name:  "pure identifier keys still suppress the combined-entropy FP",
			input: "GOOGLE_ADSENSE_ACCOUNT=pub-1234567890123456",
			want:  "GOOGLE_ADSENSE_ACCOUNT=pub-1234567890123456",
		},
