	"context"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli"
)

func main() {
	client, err := cli.NewAuthenticatedAPIClient(context.Background(), false)
	if err != nil {
		log.Fatal(err)
	}
	resp, err := client.Get(context.Background(), "/api/v1/trails/gh/entireio/cli/372")
	if err != nil {
		log.Fatal(err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
		log.Fatalf("status %s: %s", resp.Status, body)
	}
	var document any
	if err := json.NewDecoder(resp.Body).Decode(&document); err != nil {
		log.Fatal(err)
	}
	walk("$", document)
}

func walk(path string, value any) {
	switch typed := value.(type) {
	case map[string]any:
		for key, child := range typed {
			childPath := path + "." + key
			lower := strings.ToLower(key)
			if strings.Contains(lower, "risk") || strings.Contains(lower, "score") || strings.Contains(lower, "rationale") {
				encoded, _ := json.Marshal(child)
				fmt.Printf("%s = %s\n", childPath, encoded)
			}
			walk(childPath, child)
		}
	case []any:
		for index, child := range typed {
			walk(fmt.Sprintf("%s[%d]", path, index), child)
		}
	}
}

